<script setup lang="ts">
import {useRouter} from 'vue-router';import {showConfirmDialog} from 'vant';import {session,clearSession} from '../store';import {request} from '../api';
const router=useRouter();async function logout(){try{await showConfirmDialog({title:'退出登录',message:'退出当前账号？'})}catch{return}try{await request('/logout',{method:'POST'})}catch{}clearSession();await router.replace('/');location.reload()}
</script><template><main class="page"><header class="page-header"><div><span class="eyebrow">ACCOUNT</span><h1>我的</h1></div></header><section class="profile-card"><div class="avatar large">{{(session.user.nickname||'我').slice(0,1)}}</div><h2>{{session.user.nickname||session.user.username}}</h2><p>{{session.user.username}}</p></section><van-cell-group inset><van-cell title="手机号码" :value="session.user.mobile||'未填写'"/><van-cell title="邮箱" :value="session.user.email||'未填写'"/><van-cell title="切换电脑版" icon="desktop-o" is-link url="/"/></van-cell-group><van-cell title="编辑个人资料与密码" is-link to="/profile"/><van-cell title="全部业务与系统应用" is-link to="/apps"/><van-button block plain class="logout-button" @click="logout">退出登录</van-button><p class="end-note">SF 管理系统 · 移动工作台</p></main></template>
